cat <<'EOF' | node --input-type=module
import { registerHooks } from 'node:module';
import { existsSync } from 'node:fs';
registerHooks({ resolve(specifier, context, next) {
  if (specifier.startsWith('.') && specifier.endsWith('.js') && context.parentURL?.startsWith('file:')) {
    const url = new URL(specifier, context.parentURL);
    const source = new URL(url.href.replace('/dist/', '/src/').replace(/\.js$/, '.ts'));
    if (source.href.includes('/src/') && existsSync(source)) return next(source.href, context);
  }
  return next(specifier, context);
}});
const { installVendor } = await import('./tools/node-vendor.mjs');
await installVendor({reference: true});
const { Program } = await import('./src/typed/program.ts');
const { projectSource } = await import('./src/typed/project.ts');
const B = await import('./src/typed/backend/index.ts');
const source = `function probe(code: buffer, entry: i32, x: i32): i32 {
    const stack = new Int32Array(4);
    const locals = new Int32Array(4);
    locals[0] = x;
    let pc: i32 = entry;
    let sp: i32 = 0;
    loop {
        const op = code.charCodeAt(pc);
        const arg = code.charCodeAt(pc + 1);
        pc = pc + 2;
        if (op === 1) {
            stack[sp] = locals[arg];
            sp = sp + 1;
        } else if (op === 0) {
            return stack[sp - 1];
        }
    }
    return 0;
}`;
const meta = { sources: ['main.typed'], pipeline: 'speed', focus: 7, inputs: { probe: { code: { cells: [1, 0, 0, 0, 1, 0, 0, 0] }, entry: { oneOf: [0, 4] }, x: [-8, 8] } } };
const ps = projectSource('vm-probe', { 'main.typed': source, 'project.json': JSON.stringify(meta) });
const p = Program.fromProject(ps);
console.log('project', ps.meta, p.status, p.error);
if (p.status !== 'ok') process.exit(1);
const cases = p.cases('probe', {count: 8, seed: 7});
const r0Image = B.lowerToImage(p.head).image;
const ref = globalThis.typedRv32.compile(ps.source, [], undefined);
const refImage = B.imageFromCode('probe', ref.image, ref.entries);
const steps = await p.pipeline('speed');
const speedImage = B.lowerToImage(p.head).image;
for (const c of cases) {
  const ir = p.exec('probe', [[1, 0, 0, 0, 1, 0, 0, 0], c.args[1], c.args[2]], { limit: 2e4 });
  const runs = [r0Image, speedImage, refImage].map(img => B.runImage(img, c.fn, c.args, c.memory, { limit: 2e5 }));
  console.log(c.args.slice(1), [ir, ...runs].map(r => ({result:r.result, trap:r.trap, steps:r.steps})));
  if ([ir,...runs].some(r => r.trap || r.result !== c.args[2])) process.exitCode = 1;
}
console.log('pipe', steps);
EOF

