    locals[0] = x;
    let pc: i32 = entry;
    let sp: i32 = 0;
    while (true) {
        const op = code.charCodeAt(pc);
        const arg = code.charCodeAt(pc + 1);
        pc = pc + 2;
        if (op === 1) {
            stack[sp] = locals[arg];
            sp = sp + 1;
        } else if (op === 0) {
            return stack[sp - 1];
        } else {
            return 0;
        }
    }
    return 0;
}\`;
const cells = [1, 0, 0, 0, 1, 0, 0, 0];
const meta = { sources: ['main.typed'], pipeline: 'speed', focus: 7, ingest: {tape:true}, inputs: { probe: { code: { cells }, entry: { oneOf: [0, 4] }, x: [-8, 8] } } };
const ps = projectSource('vm-probe', { 'main.typed': source, 'project.json': JSON.stringify(meta) });
const p0 = Program.fromProject(ps);
console.log('default', p0.status, p0.error);
const p = new Program(ps.name, ps.source, {inputs: ps.meta.inputs, fileMap: ps.fileMap, ingest: ps.meta.ingest});
console.log('tape', p.status, p.error, ps.fileMap, ps.meta.pipeline);
assert.equal(p.status, 'ok');
const base = storeOf(p.head.value);
const cases = casesFrom(base, 'probe', { count: 8, seed: 7, inputs: p.inputs.probe });
const r0Image = B.lowerToImage(p.head).image;
const ref = globalThis.typedRv32.compile(ps.source, [], undefined);
const refImage = B.imageFromCode('probe', ref.image, ref.entries);
const pipeline = await p.pipeline('speed');
const speedImage = B.lowerToImage(p.head).image;
for (const c of cases) {
