node --input-type=module <<'EOF'
import assert from 'node:assert/strict';
import {readFileSync} from 'node:fs';
const doc = readFileSync('ttmp/2026/11/26/IRWB-012--bytecode-vm/design-doc/01-a-stack-machine-bytecode-vm-for-specialization.md','utf8');
const {inputs:{runVm:{code:{cells}, entry:{oneOf:entries}, n, seed}}} = JSON.parse(doc.match(/```json
([\s\S]*?)
```/)[1]);
assert.equal(cells.length,64);
const fixtures = [[0, 30, 34, 15], [34, 60, 64, 13]];
for (const [entry, exit, end, body] of fixtures) {
  assert.ok(entries.includes(entry));
  assert.deepEqual(cells.slice(entry, entry + 4), [2, 0, 7, exit]);
  assert.deepEqual(cells.slice(exit - 10, exit), [2, 0, 1, 1, 5, 0, 3, 0, 8, entry]);
  assert.deepEqual(cells.slice(exit, end), [2, entry === 0 ? 2 : 1, 0, 0]);
  let depth = 0, peak = 0;
  for (let pc = entry; pc < exit; pc += 2) {
    const [op, arg] = cells.slice(pc, pc + 2);
    assert.ok(op >= 1 && op <= 8);
    if (op === 2 || op === 3) assert.ok(arg >= 0 && arg < 4);
    if ([4,5,6].includes(op)) assert.ok(depth >= 2);
    depth += [0,1,1,-1,-1,-1,-1,-1,0][op];
    assert.ok(depth >= 0);
    peak = Math.max(peak, depth);
  }
  assert.equal(depth,0);
  assert.equal(peak,2);
  assert.equal((exit - entry) / 2,body);
  console.log({entry, exit, peak, maxDispatches: body * n[1] + 4});
}
assert.equal(entries.length * (n[1]-n[0]+1) * (seed[1]-seed[0]+1), 442);
assert.equal(128 + 64 * 184, 11904);
EOF

